{
  "nodes": [
    {
      "id": "n1",
      "goal": "Query the sqlite database to find the power_id corresponding to 'Super Strength' power name",
      "depends_on": [],
      "suggested_tools": ["execute_context_sql"],
      "expected_output": "A single integer value representing the power_id for 'Super Strength'"
    },
    {
      "id": "n2",
      "goal": "Read the superhero.csv file to extract superhero_id and height_cm columns for all superheroes",
      "depends_on": [],
      "suggested_tools": ["read_csv"],
      "expected_output": "A dataframe containing superhero id and height_cm columns"
    },
    {
      "id": "n3",
      "goal": "Join the power_id lookup from n1 with hero_power table to get hero_ids having Super Strength, then filter by height > 200cm from n2 and count the results",
      "depends_on": ["n1", "n2"],
      "suggested_tools": ["execute_context_sql", "query_dataframe"],
      "expected_output": "A single integer count of superheroes with Super Strength power and height over 200cm"
    }
  ],
  "final_node_id": "n3"
}

